23. import { GroupId, SpecId } from '../utils/ids';
24. import { SeriesCompareFn } from '../utils/series_sort';
25. import { PartialTheme, PointStyle, Theme } from '../utils/themes/theme';
26. /** @public */
27. export interface LayerValue {
28.     /**
29.      * The category value as retrieved by the `groupByRollup` callback
30.      */
31.     groupByRollup: PrimitiveValue;
32.     /**
33.      * The small multiples `<GroupBy>` `by` accessor value, to specify which small multiples panel is interacted with
34.      */
35.     smAccessorValue: ReturnType<GroupByAccessor>;
36.     /**
37.      * Numerical value of the partition
38.      */
39.     value: number;
40.     /**
41.      * The position index of the sub-partition within its containing partition
42.      */
43.     sortIndex: number;
44.     /**
45.      * The depth of the partition in terms of the layered partition tree, where
46.      * 0 is root (single, not visualized root of the partitioning tree),
47.      * 1 is pie chart slices and innermost layer of sunburst, or 1st level treemap/flame/icicle breakdown
48.      * 2 and above are increasingly outer layers
49.      * maximum value is on the deepest leaf node
50.      */
51.     depth: number;
52.     /**
53.      * It contains the full path of the partition node, which is an array of `{index, value}` tuples
54.      * where `index` corresponds to `sortIndex` and `value` corresponds `groupByRollup`
55.      */
56.     path: LegendPath;
57. }
58. /** @public */
59. export interface FlameLayerValue {
60.     /**
61.      * The zero-based index of the data point
62.      */
63.     vmIndex: number;
64. }
65. /** @public */
66. export interface GroupBrushExtent {
67.     groupId: GroupId;
68.     extent: [number, number];
69. }
70. /** @public */
71. export interface XYBrushEvent {
72.     x?: [number, number];
73.     y?: Array<GroupBrushExtent>;
74. }
75. /** @public */
76. export type XYChartElementEvent = [geometry: GeometryValue, seriesIdentifier: XYChartSeriesIdentifier];
77. /** @public */
78. export type PartitionElementEvent = [layers: Array<LayerValue>, seriesIdentifier: SeriesIdentifier];
79. /** @public */
80. export type FlameElementEvent = FlameLayerValue;
81. /** @public */
82. export type HeatmapElementEvent = [cell: Cell, seriesIdentifier: SeriesIdentifier];
83. /** @public */
84. export type WordCloudElementEvent = [model: WordModel, seriesIdentifier: SeriesIdentifier];
85. /**
86.  * Describes a Metric element that is the subject of an interaction.
87.  * In particular, it reports the index of the metric within the two-dimensional data array
88.  * @public
89.  */
90. export type MetricElementEvent = {
91.     type: 'metricElementEvent';
92.     rowIndex: number;
93.     columnIndex: number;
94. };
95. /**
96.  * A type-guard for MetricElementEvents
97.  * @public
98.  */
99. export declare function isMetricElementEvent(e: Parameters<ElementClickListener>[0][0]): e is MetricElementEvent;
100. /**
101.  * An object that contains the scaled mouse position based on
102.  * the current chart configuration.
103.  * @public
104.  */
105. export type ProjectedValues = {
106.     /**
107.      * The independent variable of the chart
108.      */
109.     x: PrimitiveValue;
110.     /**
111.      * The set of dependent variable, each one with its own groupId
112.      */
113.     y: Array<{
114.         value: PrimitiveValue;
115.         groupId: string;
116.     }>;
117.     /**
118.      * The categorical value used for the vertical placement of the chart
119.      * in a small multiple layout
120.      */
121.     smVerticalValue: PrimitiveValue;
122.     /**
123.      * The categorical value used for the horizontal placement of the chart
124.      * in a small multiple layout
125.      */
126.     smHorizontalValue: PrimitiveValue;
127. };
128. /**
129.  * @public
130.  * The listener type for click on the projection area.
131.  */
132. export type ProjectionClickListener = (values: ProjectedValues) => void;
133. /** @public */
134. export type ElementClickListener = (elements: Array<XYChartElementEvent | PartitionElementEvent | FlameElementEvent | HeatmapElementEvent | WordCloudElementEvent | MetricElementEvent>) => void;
135. /** @public */
136. export type ElementOverListener = (elements: Array<XYChartElementEvent | PartitionElementEvent | FlameElementEvent | HeatmapElementEvent | WordCloudElementEvent | MetricElementEvent>) => void;
137. /** @public */
138. export type BrushEvent = XYBrushEvent | HeatmapBrushEvent;
139. /** @public */
140. export type BrushEndListener = (brushAreaEvent: BrushEvent) => void;
141. /** @public */
142. export type ProjectionAreaChangeListener = (areas: {
143.     projection: Dimensions;
144.     parent: Dimensions;
145. }) => void;
146. /** @public */
147. export interface HeatmapBrushEvent extends SmallMultiplesDatum {
148.     cells: Cell[];
149.     x: (string | number)[];
150.     y: (string | number)[];
151. }
152. /** @public */
153. export type LegendItemListener = (series: SeriesIdentifier[]) => void;
154. /**
155.  * The listener type for generic mouse move
156.  *
157.  * @public
158.  */
159. export type PointerUpdateListener = (event: PointerEvent) => void;
160. /**
161.  * Listener to be called when chart resizes
162.  * @alpha
163.  */
164. export type ResizeListener = () => void;
165. /**
166.  * Listener to be called when chart render state changes
167.  *
168.  * `isRendered` value is `true` when rendering is complete and `false` otherwise
169.  * @public
170.  */
171. export type RenderChangeListener = (isRendered: boolean) => void;
172. /**
173.  * Listener to be called *before* chart renders
